package android.provider;import android.net.Uri;import android.content.ContentResolver;public class DocumentsContract{public static String EXTRA_INITIAL_URI="initial";public static boolean isDocumentUri(Object a,Uri u){return u.getAuthority().contains("documents");}public static boolean deleteDocument(ContentResolver r,Uri u)throws Exception{return r.erase(u);}public static String getDocumentId(Uri u){return u.getLastPathSegment();}}
